//! Interned names (tags, attributes, class tokens, namespace URIs).
//!
//! Ids `1..STATIC_LEN` are generated by build.rs from `data/` and mirrored in `packages/rsdom/lib/generated/atoms.cjs`;
//! they are immutable and global. Dynamic atoms (`>= STATIC_LEN`) are per-Env (one interner per napi_env,
//! no shared mutable statics). JS mirrors dynamic atoms lazily through `atomsFrom(start)` when
//! `EP[ATOM_LEN]` exceeds its table length.

use crate::atom_hash::{atom_hash, slot};

/// An interned name. `Atom(0)` means "none" (no name / null namespace).
#[derive(Clone, Copy, PartialEq, Eq, Hash, Default, Debug, PartialOrd, Ord)]
#[repr(transparent)]
pub struct Atom(pub u32);

impl Atom {
    /// No atom.
    pub const NONE: Atom = Atom(0);

    /// True for `Atom(0)`.
    #[inline(always)]
    pub fn is_none(self) -> bool {
        self.0 == 0
    }
}

mod generated {
    use super::Atom;
    include!(concat!(env!("OUT_DIR"), "/atoms.rs"));
}

pub use generated::{STATIC_ATOMS, STATIC_LEN, atom};
use generated::{STATIC_BITS, STATIC_FP, STATIC_TABLE};

/// Per-Env interner. One hash per lookup: the name is hashed once with `atom_hash` and that value probes
/// the build-generated static table, then this env's dynamic table (both open addressing, linear probing).
/// Each dynamic name is stored once (`names`); the table holds only ids.
#[derive(Default)]
pub struct Interner {
    /// Dynamic atom names; atom id = STATIC_LEN + index.
    names: Vec<Box<str>>,
    /// Hash of each dynamic name (rehash on growth without rehashing strings).
    hashes: Vec<u64>,
    /// Open-addressing table of dynamic atom ids (0 = empty); power-of-two length, load <= 1/2.
    table: Vec<u32>,
    bits: u32,
}

impl Interner {
    /// Creates an interner containing only the static atoms.
    pub fn new() -> Self {
        Self::default()
    }

    #[inline]
    fn get_hashed(&self, s: &str, h: u64) -> Option<Atom> {
        let mask = STATIC_TABLE.len() - 1;
        let mut p = slot(h, STATIC_BITS);
        loop {
            let id = STATIC_TABLE[p] as usize;
            if id == 0 {
                break;
            }
            if STATIC_FP[id] == (h >> 32) as u32 && STATIC_ATOMS[id] == s {
                return Some(Atom(id as u32));
            }
            p = (p + 1) & mask;
        }
        if self.table.is_empty() {
            return None;
        }
        let mask = self.table.len() - 1;
        let mut p = slot(h, self.bits);
        loop {
            let id = self.table[p];
            if id == 0 {
                return None;
            }
            let i = (id - STATIC_LEN) as usize;
            if self.hashes[i] == h && &*self.names[i] == s {
                return Some(Atom(id));
            }
            p = (p + 1) & mask;
        }
    }

    /// Looks up `s` without interning.
    #[inline]
    pub fn get(&self, s: &str) -> Option<Atom> {
        self.get_hashed(s, atom_hash(s.as_bytes()))
    }

    /// Interns `s`.
    #[inline]
    pub fn intern(&mut self, s: &str) -> Atom {
        let h = atom_hash(s.as_bytes());
        if let Some(a) = self.get_hashed(s, h) {
            return a;
        }
        let id = STATIC_LEN + self.names.len() as u32;
        assert!(id < (1 << 30), "rsdom: atom table limit reached");
        self.names.push(s.into());
        self.hashes.push(h);
        if (self.names.len() + 1) * 2 > self.table.len() {
            self.rehash();
        } else {
            self.insert_slot(id, h);
        }
        Atom(id)
    }

    fn insert_slot(&mut self, id: u32, h: u64) {
        let mask = self.table.len() - 1;
        let mut p = slot(h, self.bits);
        while self.table[p] != 0 {
            p = (p + 1) & mask;
        }
        self.table[p] = id;
    }

    /// Doubles the dynamic table (or creates it) and reinserts every dynamic atom.
    fn rehash(&mut self) {
        self.bits = (self.bits + 1).max(6);
        self.table = vec![0; 1 << self.bits];
        for i in 0..self.names.len() {
            self.insert_slot(STATIC_LEN + i as u32, self.hashes[i]);
        }
    }

    /// The name of `a` ("" for unknown ids and `Atom(0)`).
    #[inline]
    pub fn name(&self, a: Atom) -> &str {
        let i = a.0 as usize;
        if i < STATIC_ATOMS.len() {
            STATIC_ATOMS[i]
        } else {
            self.names.get(i - STATIC_ATOMS.len()).map_or("", |b| b)
        }
    }

    /// True if `a` names an existing atom.
    #[inline]
    pub fn is_valid(&self, a: Atom) -> bool {
        a.0 != 0 && (a.0 as usize) < STATIC_ATOMS.len() + self.names.len()
    }

    /// Total atom count including id 0 (the next dynamic id).
    #[inline]
    pub fn len(&self) -> u32 {
        STATIC_LEN + self.names.len() as u32
    }

    /// Always false (id 0 is reserved).
    pub fn is_empty(&self) -> bool {
        false
    }

    /// Dynamic atom names with id >= `start` for the JS mirror, length-prefixed (names may contain any
    /// character, NUL included): the names are concatenated into `out` and `lens` receives the UTF-16
    /// length of each, in id order.
    pub fn names_from(&self, start: u32, out: &mut String, lens: &mut Vec<u32>) {
        out.clear();
        lens.clear();
        let from = start.saturating_sub(STATIC_LEN) as usize;
        for n in self.names.iter().skip(from) {
            out.push_str(n);
            lens.push(crate::string::utf16_len(n));
        }
    }
}

/// HTML-namespace element local-name validity (DOM "valid element local name").
pub fn is_valid_element_local_name(s: &str) -> bool {
    let mut chars = s.chars();
    let Some(first) = chars.next() else { return false };
    if first.is_ascii_alphabetic() {
        return !s.bytes().any(|b| matches!(b, 0 | b'\t' | b'\n' | 0x0c | b'\r' | b' ' | b'/' | b'>'));
    }
    let name_char =
        |c: char| c.is_ascii_alphanumeric() || matches!(c, '-' | '.' | ':' | '_') || c as u32 >= 0x80;
    (first == ':' || first == '_' || first as u32 >= 0x80) && chars.all(name_char)
}

/// DOM "valid attribute local name".
pub fn is_valid_attribute_local_name(s: &str) -> bool {
    !s.is_empty()
        && !s.bytes().any(|b| matches!(b, 0 | b'\t' | b'\n' | 0x0c | b'\r' | b' ' | b'/' | b'=' | b'>'))
}

/// DOM "valid namespace prefix".
pub fn is_valid_namespace_prefix(s: &str) -> bool {
    !s.is_empty() && !s.bytes().any(|b| matches!(b, 0 | b'\t' | b'\n' | 0x0c | b'\r' | b' ' | b'/' | b'>'))
}

/// DOM "valid doctype name".
pub fn is_valid_doctype_name(s: &str) -> bool {
    !s.bytes().any(|b| matches!(b, 0 | b'\t' | b'\n' | 0x0c | b'\r' | b' ' | b'>'))
}

/// XML `Name` production (used for processing-instruction targets).
pub fn is_xml_name(s: &str) -> bool {
    fn start(c: char) -> bool {
        matches!(c, ':' | 'A'..='Z' | '_' | 'a'..='z' | '\u{C0}'..='\u{D6}' | '\u{D8}'..='\u{F6}'
            | '\u{F8}'..='\u{2FF}' | '\u{370}'..='\u{37D}' | '\u{37F}'..='\u{1FFF}' | '\u{200C}'..='\u{200D}'
            | '\u{2070}'..='\u{218F}' | '\u{2C00}'..='\u{2FEF}' | '\u{3001}'..='\u{D7FF}'
            | '\u{F900}'..='\u{FDCF}' | '\u{FDF0}'..='\u{FFFD}' | '\u{10000}'..='\u{EFFFF}')
    }
    let mut it = s.chars();
    match it.next() {
        Some(c) if start(c) => {}
        _ => return false,
    }
    it.all(|c| {
        start(c)
            || matches!(c, '-' | '.' | '0'..='9' | '\u{B7}' | '\u{300}'..='\u{36F}' | '\u{203F}'..='\u{2040}')
    })
}

#[cfg(test)]
mod tests {
    use super::*;

    #[test]
    fn static_atoms() {
        let i = Interner::new();
        assert_eq!(i.get("div"), Some(atom::DIV));
        assert_eq!(i.name(atom::FOREIGN_OBJECT), "foreignObject");
        assert_eq!(i.name(atom::ARIA_LABEL), "aria-label");
        assert_eq!(i.name(atom::NS_SVG), "http://www.w3.org/2000/svg");
        assert_eq!(i.name(atom::ONCLICK), "onclick");
        assert_eq!(i.name(atom::HASH_TEXT), "#text");
        assert!(i.get("data-testid").is_some());
    }

    #[test]
    fn dynamic_atoms() {
        let mut i = Interner::new();
        let a = i.intern("my-widget");
        assert_eq!(a.0, STATIC_LEN);
        assert_eq!(i.intern("my-widget"), a);
        assert_eq!(i.name(a), "my-widget");
        let b = i.intern("x-y");
        let nul = i.intern("tok\0en");
        let mut s = String::new();
        let mut lens = Vec::new();
        i.names_from(STATIC_LEN, &mut s, &mut lens);
        assert_eq!(s, "my-widgetx-ytok\0en");
        assert_eq!(lens, [9, 3, 6]);
        i.names_from(b.0, &mut s, &mut lens);
        assert_eq!((s.as_str(), lens.as_slice()), ("x-ytok\0en", &[3, 6][..]));
        assert_eq!(i.get("tok\0en"), Some(nul));
        assert_eq!(i.name(nul), "tok\0en");
    }

    #[test]
    fn many_dynamic_atoms_and_every_static_atom_resolve() {
        let mut i = Interner::new();
        for (id, name) in STATIC_ATOMS.iter().enumerate().skip(1) {
            assert_eq!(i.get(name), Some(Atom(id as u32)), "{name}");
            assert_eq!(i.intern(name), Atom(id as u32));
        }
        let ids: Vec<Atom> = (0..5000).map(|k| i.intern(&format!("dyn-{k}"))).collect();
        for (k, a) in ids.iter().enumerate() {
            assert_eq!(i.get(&format!("dyn-{k}")), Some(*a));
            assert_eq!(i.name(*a), format!("dyn-{k}"));
        }
        assert_eq!(i.get("dyn-5000"), None);
        assert_eq!(i.get(""), None);
    }

    #[test]
    fn name_validation() {
        assert!(is_valid_element_local_name("div"));
        assert!(is_valid_element_local_name("my-el"));
        assert!(!is_valid_element_local_name("1a"));
        assert!(!is_valid_element_local_name("a b"));
        assert!(!is_valid_element_local_name(""));
        assert!(is_valid_attribute_local_name("data-x"));
        assert!(is_valid_attribute_local_name("@click"));
        assert!(!is_valid_attribute_local_name("a=b"));
        assert!(is_xml_name("xml-stylesheet"));
        assert!(!is_xml_name("1x"));
    }
}
